#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OpType {
    Add,
    Multiply,
    LogicalAnd,
    LogicalOr,
}

fn ufunc_identity(op: OpType) -> Option<i8> {
    match op {
        // 0 is the identity for addition: x + 0 == x and 0 + x == x for all integers x
        OpType::Add => Some(0),
        // 1 is the identity for multiplication: x * 1 == x and 1 * x == x for all integers x
        OpType::Multiply => Some(1),
        // For our integer‐based logical AND/OR (nonzero = true, zero = false,
        // result = 1 for true, 0 for false), no single integer id satisfies
        // op(x, id) = x and op(id, x) = x for every integer x.
        OpType::LogicalAnd | OpType::LogicalOr => None,
    }
}

fn main() {
    assert_eq!(ufunc_identity(OpType::Add), Some(0));
    assert_eq!(ufunc_identity(OpType::Multiply), Some(1));
    assert_eq!(ufunc_identity(OpType::LogicalAnd), None);
    assert_eq!(ufunc_identity(OpType::LogicalOr), None);
    println!("All tests passed!");
}